// @name Gomoku
// @background #efe7d8
// @refresh 3600
// Gomoku, five in a row, against the computer or a second player. Tap a
// point of the grid to put your stone there; on a fine grid (a 19x19 board on
// a small screen) the first tap shows where it would go and a second tap on
// the same point places it. The first to get five in a row (across, down or
// diagonally) wins. On a frame's buttons Next walks the free points next to
// the stones and Action places a stone on the one ringed. The game in
// progress is kept in the scene's state.
import { DRAW, boardOf, chooseMove, newGame, place, readGame, takeBack, toMove } from './logic'

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

// Solid inks where the panel is colour e-paper, when the Contrast setting is Auto.
const inkPaper = (app) => (app.state.contrast || 'auto') === 'auto' && app.frame.paper === true && app.frame.color !== false

const THEMES = {
  color: {
    page: 'bg-[#efe7d8] text-[#2e2a25]',
    muted: 'text-[#7d705f]',
    title: 'text-[#5a3d22]',
    status: 'bg-[#33414f] text-white',
    button: 'bg-[#e1d6c3] text-[#2e2a25] active:bg-[#d3c5ad]',
    buttonOff: 'bg-[#e9e2d6] text-[#b4a790]',
    primary: 'bg-[#a8432f] text-white active:bg-[#8a3424]',
    card: 'bg-[#fbf7ef] border-4 border-[#33414f] text-[#2e2a25]',
    turn: 'border-2 border-[#a8432f]',
    // The board's own colors (SVG fills and strokes).
    wood: '#dcb979',
    frame: '#6b4c2c',
    grid: '#5c4326',
    black: '#24272c',
    blackEdge: '#0e0f11',
    white: '#f7f4ee',
    whiteEdge: '#8d7a5c',
    accent: '#c2452d',
  },
  // Colour e-paper (a Spectra's six inks), when the Contrast setting is Auto:
  // solid inks alone, a yellow board on white paper (a tan one dithers into
  // confetti with the grid lost in it).
  ink: {
    page: 'bg-white text-black',
    muted: 'text-black',
    title: 'text-black',
    status: 'bg-black text-white',
    button: 'bg-white text-black border-2 border-black',
    buttonOff: 'bg-white text-black line-through',
    primary: 'bg-[#cc0000] text-white',
    card: 'bg-white border-4 border-black text-black',
    turn: 'border-2 border-[#cc0000]',
    wood: '#ffff00',
    frame: '#000000',
    grid: '#000000',
    black: '#000000',
    blackEdge: '#000000',
    white: '#ffffff',
    whiteEdge: '#000000',
    accent: '#cc0000',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    title: 'text-black',
    status: 'bg-black text-white',
    button: 'bg-white text-black border-2 border-black',
    buttonOff: 'bg-white text-black',
    primary: 'bg-black text-white',
    card: 'bg-white border-4 border-black text-black',
    turn: 'border-4 border-black',
    wood: '#ffffff',
    frame: '#000000',
    grid: '#000000',
    black: '#000000',
    blackEdge: '#000000',
    white: '#ffffff',
    whiteEdge: '#000000',
    accent: '#000000',
  },
}

const settings = (app) => {
  const size = parseInt(app.state.size, 10)
  return {
    versus: app.state.mode !== 'two',
    level: ['easy', 'medium', 'hard'].indexOf(app.state.difficulty) >= 0 ? app.state.difficulty : 'medium',
    size: size === 13 || size === 19 ? size : 15,
    // Against the computer: the color you play (1 black, who starts, or 2 white).
    human: app.state.youPlay === 'white' ? 2 : 1,
    exact: app.state.rule === 'exact',
    confirm: app.state.confirm === 'on' || app.state.confirm === 'off' ? app.state.confirm : 'auto',
  }
}

const save = (game) => frameos.setState('game', game)
const copyOf = (game) => readGame(JSON.parse(JSON.stringify(game)))

/** The computer's stone, when it is its turn. */
const computerMoves = (game, s) => {
  if (!s.versus || game.winner || toMove(game) === s.human) return false
  const started = Date.now()
  const idx = chooseMove(game, s.level)
  place(game, idx, s.exact)
  frameos.log(`gomoku: computer (${s.level}) replied in ${Date.now() - started} ms`)
  return true
}

const loadGame = (app, s) => {
  const kept = readGame(app.state.game)
  if (kept && kept.size === s.size) {
    // The computer's turn: a game it starts, or the players setting just changed.
    if (computerMoves(kept, s)) save(kept)
    return kept
  }
  const game = newGame(s.size, Date.now() % 2147483647)
  computerMoves(game, s)
  save(game)
  return game
}

const startOver = (app, game) => {
  const s = settings(app)
  frameos.remember('confirm', false)
  frameos.remember('ghost', -1)
  const fresh = newGame(s.size, (Date.now() ^ (game.seed * 7919)) % 2147483647)
  computerMoves(fresh, s)
  save(fresh)
}

const askNewGame = (app) => {
  const game = loadGame(app, settings(app))
  if (!game.moves.length || game.winner) startOver(app, game)
  else frameos.remember('confirm', true)
}

/** The game with the last move taken back (against the computer, back to your turn), or null. */
const undone = (s, game) => {
  const g = copyOf(game)
  if (!takeBack(g)) return null
  if (s.versus && toMove(g) !== s.human && !takeBack(g)) return null
  if (s.versus && toMove(g) !== s.human) return null
  return g
}

// What each point holds (0 empty, 1 black, 2 white), one signal a point, and
// the marks and lines a move changes: a tap runs only what reads them, not
// get(). The game itself stays in the scene's `game` field.
let stones = []
const lastMove = signal(-1) // the point with the last stone's dot, -1 none
const winLine = signal('') // the five's two ends, "a,b", or ""
const ghost = signal(-1)
const turnShown = signal(0) // whose turn the players' row shows, 0 when the game is over
const status = signal('')
const played = signal(0)
const canUndo = signal(false)
// The points the keys walk (docs/jsx-ui.md "Keys"): the free points next to a
// stone (the middle on an empty board), as a list "i,i,...", each an element
// with its own onClick. Not all of them: a 15x15 board is 225 presses round.
// `nearAt` is the same set, for the board's own handler of a finger.
const near = signal('')
let nearAt = new Set()

/** Every signal from the game and what the scene remembers. */
const show = (app, game) => {
  const s = settings(app)
  const n = game.size
  if (stones.length !== n * n) stones = Array.from({ length: n * n }, () => signal(0))
  const cells = boardOf(game)
  for (let i = 0; i < cells.length; i++) stones[i].value = cells[i]
  const turn = toMove(game)
  const yourTurn = !game.winner && !(s.versus && turn !== s.human)
  const g = yourTurn ? frameos.recall('ghost') ?? -1 : -1
  const colorName = (c) => (c === 1 ? 'Black' : 'White')
  let line
  if (game.winner === DRAW) line = 'Draw: the board is full'
  else if (game.winner) line = s.versus ? (game.winner === s.human ? 'You win!' : 'The computer wins') : `${colorName(game.winner)} wins!`
  else if (g >= 0) line = 'Tap again to place'
  else if (s.versus) line = 'Your move'
  else line = `${colorName(turn)} to move`
  lastMove.value = game.moves.length && !game.winner ? game.moves[game.moves.length - 1] : -1
  winLine.value = game.line.length >= 2 ? `${game.line[0]},${game.line[game.line.length - 1]}` : ''
  ghost.value = g
  turnShown.value = game.winner ? 0 : turn
  status.value = line
  played.value = game.moves.length
  canUndo.value = !frameos.recall('confirm') && !!undone(s, game)
  const points = []
  if (yourTurn && !frameos.recall('confirm')) {
    if (!game.moves.length) points.push(Math.floor(n / 2) * n + Math.floor(n / 2))
    else {
      for (let i = 0; i < n * n; i++) {
        if (cells[i]) continue
        const r = Math.floor(i / n)
        const c = i % n
        let by = false
        for (let dr = -1; dr <= 1 && !by; dr++) {
          for (let dc = -1; dc <= 1 && !by; dc++) {
            const rr = r + dr
            const cc = c + dc
            if ((dr || dc) && rr >= 0 && rr < n && cc >= 0 && cc < n && cells[rr * n + cc]) by = true
          }
        }
        if (by) points.push(i)
      }
    }
  }
  near.value = points.join(',')
  nearAt = new Set(points)
}

const undo = (app): boolean => {
  const g = undone(settings(app), loadGame(app, settings(app)))
  if (!g) return false
  frameos.remember('ghost', -1)
  save(g)
  show(app, g)
  return true
}

/** Puts the stone of the side to move on `idx`, and the computer answers. */
const playAt = (app, game, idx) => {
  const s = settings(app)
  const g = copyOf(game)
  if (!place(g, idx, s.exact)) return false
  frameos.remember('ghost', -1)
  computerMoves(g, s)
  save(g)
  show(app, g)
  return true
}

/** A tap on the point `idx`: with two-tap placing, the first one only shows where. */
const tapPoint = (app, idx, twoTaps) => {
  const s = settings(app)
  const game = loadGame(app, s)
  if (game.winner || frameos.recall('confirm')) return
  if (s.versus && toMove(game) !== s.human) return
  if (boardOf(game)[idx]) {
    frameos.remember('ghost', -1)
    show(app, game)
    return
  }
  if (twoTaps && frameos.recall('ghost') !== idx) {
    frameos.remember('ghost', idx)
    show(app, game)
    return
  }
  playAt(app, game, idx)
}

// A keyboard on a Pi: the arrows move a cursor, Enter or space places a stone.
// Tab puts the cursor away and walks the keys' ring (docs/jsx-ui.md "Keys"),
// whose Enter is the ringed element's.
export function onEvent(app, context) {
  const s = settings(app)
  const game = loadGame(app, s)
  const p = context.payload || {}
  // The frame's back closes the "New game?" question, else takes back a
  // move; with nothing to take back it is the frame's.
  if (context.event === 'back') {
    if (frameos.recall('confirm')) {
      frameos.remember('confirm', false)
      return true
    }
    return undo(app)
  }
  if (context.event !== 'keyDown' || p.ctrl || p.alt || p.meta) return false
  const key = String(p.key || '')
  if (key === 'Tab') {
    if (frameos.recall('keys')) frameos.remember('keys', false)
    return false
  }
  if (frameos.recall('confirm')) {
    if ((key === 'Enter' && frameos.recall('keys')) || key === 'y') startOver(app, game)
    else if (key === 'Escape' || key === 'n') frameos.remember('confirm', false)
    else return false
    return true
  }
  const n = game.size
  const center = Math.floor(n / 2) * n + Math.floor(n / 2)
  const cursor = frameos.recall('cursor') ?? center
  const steps = { ArrowUp: [-1, 0], ArrowDown: [1, 0], ArrowLeft: [0, -1], ArrowRight: [0, 1] }
  if (key in steps) {
    const r = Math.max(0, Math.min(n - 1, Math.floor(cursor / n) + steps[key][0]))
    const c = Math.max(0, Math.min(n - 1, (cursor % n) + steps[key][1]))
    frameos.remember('cursor', r * n + c)
    frameos.remember('keys', true)
    return true
  }
  if ((key === 'Enter' && frameos.recall('keys')) || key === ' ') {
    frameos.remember('keys', true)
    if (!game.winner && !(s.versus && toMove(game) !== s.human)) playAt(app, game, cursor)
    return true
  }
  if (key === 'u' || key === 'Backspace') {
    undo(app)
    return true
  }
  if (key === 'n') {
    askNewGame(app)
    return true
  }
  return false
}

// The star points of each board size, where the eye finds its way.
const STARS = { 13: [3, 6, 9], 15: [3, 7, 11], 19: [3, 9, 15] }

// The board's parts a move changes, each reading its signals; drawn in the
// order they always were (stones, the last stone's dot, the five, the ghost).
const Stone = memo(({ i, n, px, t, hc }) => {
  const v = stones[i].value
  if (!v) return <g />
  const g = px / n
  const at = (k) => (k + 0.5) * g
  const r = g * 0.45
  const cx = at(i % n)
  const cy = at(Math.floor(i / n))
  return v === 1 ? (
    <circle cx={cx} cy={cy} r={r} fill={t.black} stroke={t.blackEdge} strokeWidth={g * 0.03} />
  ) : (
    <circle cx={cx} cy={cy} r={r - g * 0.03} fill={t.white} stroke={t.whiteEdge} strokeWidth={g * (hc ? 0.08 : 0.05)} />
  )
})

// The last stone gets a dot in the other color (the accent in color).
const LastMark = memo(({ n, px, t, hc }) => {
  const last = lastMove.value
  if (last < 0) return <g />
  const g = px / n
  const at = (k) => (k + 0.5) * g
  const fill = hc ? (stones[last].value === 1 ? '#ffffff' : '#000000') : t.accent
  return <circle cx={at(last % n)} cy={at(Math.floor(last / n))} r={g * 0.15} fill={fill} />
})

// The five in a row: a band over the stones, white around black in high contrast.
const WinLine = memo(({ n, px, t, hc }) => {
  if (!winLine.value) return <g />
  const [a, b] = winLine.value.split(',').map(Number)
  const g = px / n
  const at = (k) => (k + 0.5) * g
  const x1 = at(a % n)
  const y1 = at(Math.floor(a / n))
  const x2 = at(b % n)
  const y2 = at(Math.floor(b / n))
  return (
    <g>
      <line x1={x1} y1={y1} x2={x2} y2={y2} stroke="#ffffff" strokeWidth={g * 0.36} strokeLinecap="round" />
      <line x1={x1} y1={y1} x2={x2} y2={y2} stroke={hc ? '#000000' : t.accent} strokeWidth={g * 0.2} strokeLinecap="round" />
    </g>
  )
})

// Where a first tap would put the stone: a small stone in the corners of a
// square, which no stone on the board looks like.
const GhostMark = memo(({ n, px, t, hc }) => {
  const at0 = ghost.value
  if (at0 < 0) return <g />
  const ghostColor = turnShown.value
  const g = px / n
  const at = (k) => (k + 0.5) * g
  const r = g * 0.45
  const gx = at(at0 % n)
  const gy = at(Math.floor(at0 / n))
  const h = g * 0.5
  const arm = g * 0.22
  const ink = hc ? '#000000' : t.accent
  const corner = (sx, sy) => (
    <polyline points={`${gx + sx * h},${gy + sy * (h - arm)} ${gx + sx * h},${gy + sy * h} ${gx + sx * (h - arm)},${gy + sy * h}`}
      fill="none" stroke={ink} strokeWidth={Math.max(2, g * 0.09)} strokeLinecap="round" strokeLinejoin="round" />
  )
  return (
    <g>
      {corner(-1, -1)}
      {corner(1, -1)}
      {corner(-1, 1)}
      {corner(1, 1)}
      <circle cx={gx} cy={gy} r={r * 0.55} fill={ghostColor === 1 ? t.black : t.white} stroke={ghostColor === 1 ? t.blackEdge : t.whiteEdge} strokeWidth={g * 0.05} />
    </g>
  )
})

const Board = ({ n, px, t, hc, cursor }) => {
  const g = px / n
  const at = (i) => (i + 0.5) * g
  const lineWidth = Math.max(1, Math.round(g * (hc ? 0.06 : 0.045) * 10) / 10)
  const grid = []
  for (let i = 0; i < n; i++) {
    grid.push(<line x1={at(0)} y1={at(i)} x2={at(n - 1)} y2={at(i)} stroke={t.grid} strokeWidth={lineWidth} />)
    grid.push(<line x1={at(i)} y1={at(0)} x2={at(i)} y2={at(n - 1)} stroke={t.grid} strokeWidth={lineWidth} />)
  }
  const stars = []
  for (const r of STARS[n]) for (const c of STARS[n]) stars.push(<circle cx={at(c)} cy={at(r)} r={g * 0.11} fill={t.grid} />)
  const points = []
  for (let i = 0; i < n * n; i++) points.push(<Stone i={i} n={n} px={px} t={t} hc={hc} />)
  const cursorMark =
    cursor >= 0 ? (
      <rect x={at(cursor % n) - g / 2 + 1} y={at(Math.floor(cursor / n)) - g / 2 + 1} width={g - 2} height={g - 2} fill="none"
        stroke={hc ? '#000000' : t.accent} strokeWidth={Math.max(2, g * 0.08)} />
    ) : null
  return (
    <svg viewBox={`0 0 ${px} ${px}`} width={px} height={px}>
      <rect width={px} height={px} fill={t.wood} />
      {grid}
      {stars}
      {points}
      <LastMark n={n} px={px} t={t} hc={hc} />
      <WinLine n={n} px={px} t={t} hc={hc} />
      <GhostMark n={n} px={px} t={t} hc={hc} />
      {cursorMark}
    </svg>
  )
}

// The points the keys walk, over the board: each its own element with an
// onClick, so Next rings it. Action places the stone at once (the ring shows
// where); a finger's tap goes as a tap anywhere on the board does.
const Near = memo(({ n, px, app, twoTaps }) => {
  const at = (k: number) => Math.round((k * px) / n)
  return (
    <div className="absolute left-0 top-0 w-full h-full">
      {near.value ? near.value.split(',').map(Number).map((i) => (
        <div className={`absolute left-[${at(i % n)}px] top-[${at(Math.floor(i / n))}px] w-[${at((i % n) + 1) - at(i % n)}px] h-[${at(Math.floor(i / n) + 1) - at(Math.floor(i / n))}px]`}
          onClick={(e) => tapPoint(app, i, twoTaps && !e.key)} />
      )) : null}
    </div>
  )
})

/** A stone as a small icon. */
const StoneIcon = ({ color, px, t }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px}px] h-[${px}px]`}>
    {color === 1 ? (
      <circle cx={12} cy={12} r={10} fill={t.black} stroke={t.blackEdge} strokeWidth={1.5} />
    ) : (
      <circle cx={12} cy={12} r={9.5} fill={t.white} stroke={t.whiteEdge} strokeWidth={2.5} />
    )}
  </svg>
)

// The players' row, the status, the count and Undo: each reads its signals.
const Status = memo(({ cls }) => <div className={cls}>{status.value}</div>)
// A player: the stone with the name beside it, or (`stacked`, where a row has
// little room) the name small under the stone, or (`bare`, a round panel's
// narrow arc) the stone alone. The one to move is outlined.
const nameSize = (font) => Math.max(10, Math.round(font * 0.62))
const Player = memo(({ c, stacked, bare, font, small, t, label }) => stacked ? (
  <div className={`flex flex-col items-center gap-[2px] rounded-xl px-1 py-[2px] ${turnShown.value === c ? t.turn : 'border-2 border-transparent'}`}>
    <StoneIcon color={c} px={Math.round(font * 1.15)} t={t} />
    {bare ? null : <span className={`text-[${small || nameSize(font)}px] font-bold leading-none whitespace-nowrap`}>{label}</span>}
  </div>
) : (
  <div className={`flex items-center gap-2 rounded-xl px-2 py-1 ${turnShown.value === c ? t.turn : 'border-2 border-transparent'}`}>
    <StoneIcon color={c} px={Math.round(font * 1.3)} t={t} />
    <span className={`text-[${font}px] font-bold`}>{label}</span>
  </div>
))
const Played = memo(({ cls }) => <span className={cls}>{`${played.value} stones played`}</span>)
const UndoButton = memo(({ cls, t, app }) => (
  <div className={`${cls} ${canUndo.value ? t.button : t.buttonOff}`} onClick={() => undo(app)}>
    Undo
  </div>
))

// A round panel (only the circle inside the square shows): the board in the
// square inside the circle, the status in the arc above, each player's stone
// in the arcs left and right of it, Undo and New game in the arc below.
const roundRoom = (W: number, H: number) => {
  const r = Math.min(W, H) / 2
  const side = Math.floor((r - 12) * Math.SQRT2)
  // How wide a row may be whose far edge is dy px from the centre.
  const chord = (dy: number) => Math.floor(2 * Math.sqrt(Math.max(0, (r - 12) * (r - 12) - dy * dy)))
  return { side, x0: (W - side) >> 1, y0: (H - side) >> 1, chord }
}

export function get(app, context) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const round = context.round === true
  const hc = highContrast(app)
  const t = hc ? THEMES.high : inkPaper(app) ? THEMES.ink : THEMES.color
  const s = settings(app)
  const game = loadGame(app, s)
  show(app, game)
  const n = game.size
  const confirm = !!frameos.recall('confirm')

  const m = Math.round(Math.min(W, H) * 0.04)
  const wide = W >= H * 1.2
  // A tall screen has room for the name over the status.
  const titled = !wide && H >= W * 1.4
  const headerH = wide ? 0 : Math.round(Math.max(48, H * 0.09))
  const titleH = titled ? Math.round(H * 0.08) : 0
  const footH = wide ? 0 : Math.round(Math.max(52, Math.min(H * 0.1, 88)))
  const pad = Math.round(m * 0.4)
  const board = Math.floor((round ? roundRoom(W, H).side : wide ? Math.min(H - 2 * m, (W - 3 * m) * 0.64) : Math.min(W - 2 * m, H - headerH - titleH - footH - (titled ? 5 : 4) * m)) - 2 * pad)
  const outer = board + 2 * pad
  const panelW = wide ? W - outer - 3 * m : W - 2 * m
  const colorName = (c) => (c === 1 ? 'Black' : 'White')
  const name = (c) => (s.versus ? (c === s.human ? 'You' : 'Computer') : colorName(c))
  const rule = s.exact ? 'exactly five' : 'five in a row'
  const subtitle = `${n}×${n}, ${rule}${s.versus ? `, ${s.level}` : ', two players'}`

  // Beside the board on a wide panel, top to bottom: the name, the status,
  // the players and the buttons, the type as big as the column's width and
  // its height take. Undo goes over New game where the two side by side
  // would not fit their words, and a short column leaves the subtitle and the
  // count out (`level` 1), then puts the two players on one line, each name
  // small under its stone (`level` 2).
  const colH = H - 2 * m
  const start = Math.round(Math.max(16, Math.min(wide ? panelW * 0.075 : W * 0.045, 40)))
  const stackedAt = (f) => panelW < 2 * Math.round(5.76 * f) + 12
  const buttonAt = (f) => Math.round(Math.max(wide && colH < 320 ? 34 : 48, Math.min(f * 2.4, 96)))
  const titleAt = (f) => Math.min(Math.round(f * 2), Math.floor(panelW / 4))
  const statusPad = (f) => Math.round(Math.min(12, f * 0.5))
  const colNeed = (f, level) => {
    const sub = level ? 0 : Math.round(f * 0.75 * 1.3) * (1 + Math.ceil((subtitle.length * 0.5 * f * 0.75) / panelW))
    const players = level === 2 ? Math.round(f * 1.15) + nameSize(f) + 14 : 2 * (Math.round(f * 1.3) + 12) + 8
    const buttons = stackedAt(f) ? 2 * buttonAt(f) + 8 : buttonAt(f)
    return titleAt(f) + sub + 2 * Math.round(f * 1.25) + 2 * statusPad(f) + players + buttons + 36
  }
  // How wide the players are: a row each with the longer name, or the two
  // side by side, the names small.
  const longest = Math.max(name(1).length, name(2).length)
  const colWide = (f, level) => level === 2
    ? 2 * Math.round(nameSize(f) * 0.6 * longest + 12) + 8 <= panelW
    : Math.round(f * 1.3) + Math.round(f * 0.6 * longest) + 28 <= panelW
  let font = start
  let level = 0
  if (wide) {
    for (; level < 3; level++) {
      font = start
      const least = level === 2 ? 12 : 14
      while (font > least && (colNeed(font, level) > colH || !colWide(font, level))) font--
      if (colNeed(font, level) <= colH && colWide(font, level)) break
    }
    level = Math.min(level, 2)
  }
  const stacked = wide && stackedAt(font)
  const buttonH = buttonAt(font)

  // Two taps to place where a point of the grid is smaller than a fingertip.
  const pitch = board / n
  const twoTaps = s.confirm === 'on' || (s.confirm === 'auto' && pitch < 32)
  const cursor = frameos.recall('keys') ? frameos.recall('cursor') ?? Math.floor(n / 2) * n + Math.floor(n / 2) : -1


  // A card over the board (New game?), as wide as the board, its type sized
  // to it: its two buttons side by side where their words fit, one over the
  // other where not, and its line left out where the card would not fit the
  // board with it.
  const cardW = Math.round(board * 0.88)
  const cardPad = Math.round(Math.max(8, board * 0.05))
  const cardIn = cardW - 2 * cardPad - 8
  const cardFont = Math.max(12, Math.min(font, Math.round(board * 0.065)))
  const cardTitle = Math.max(cardFont + 2, Math.min(Math.round(board * 0.08), Math.floor(cardIn / 5.6)))
  const cardLine = Math.round(Math.max(Math.min(16, cardFont), board * 0.042))
  const cardButtonH = Math.round(Math.max(32, Math.min(buttonH, cardFont * 2.4)))
  const cardButtonPad = Math.round(cardFont * 0.9)
  const card = (title, line, labels, buttons) => {
    const side = (labels.join('').length * 0.62 * cardFont) + labels.length * 2 * cardButtonPad + 12 <= cardIn
    const lines = Math.ceil((String(line || '').length * 0.5 * cardLine) / cardIn)
    const need = 2 * cardPad + 8 + Math.round(cardTitle * 1.25) + 12 + (side ? cardButtonH : buttons.length * (cardButtonH + 8))
    const showLine = line && need + 12 + lines * Math.round(cardLine * 1.3) <= board
    return (
      <div className={`absolute left-0 top-0 w-[${outer}px] h-[${outer}px] flex items-center justify-center`}>
        <div className={`w-[${cardW}px] rounded-2xl p-[${cardPad}px] flex flex-col items-center gap-3 ${t.card}`}>
          <span className={`text-[${cardTitle}px] font-bold text-center leading-tight`}>{title}</span>
          {showLine ? <span className={`text-[${cardLine}px] text-center`}>{line}</span> : null}
          <div className={side ? 'flex gap-3' : 'flex flex-col w-full gap-2'}>{buttons}</div>
        </div>
      </div>
    )
  }
  const cardButton = (label, cls, onClick) => (
    <div className={`h-[${cardButtonH}px] px-[${cardButtonPad}px] rounded-xl flex items-center justify-center whitespace-nowrap text-[${cardFont}px] font-bold ${cls}`} onClick={onClick}>
      {label}
    </div>
  )
  // Asking for a new game, and the answers, set no signal: get() draws the card.
  const overlay = confirm
    ? card('New game?', 'The game in progress will be lost.', ['Cancel', 'New game'], [
        cardButton('Cancel', t.button, () => frameos.remember('confirm', false)),
        cardButton('New game', t.primary, () => startOver(app, loadGame(app, settings(app)))),
      ])
    : null

  const boardBox = (
    <div className={`relative shrink-0 p-[${pad}px] rounded-lg bg-[${t.frame}]`}>
      <div className={`relative w-[${board}px] h-[${board}px]`}
        onPointerUp={(e) => {
          const c = Math.max(0, Math.min(n - 1, Math.floor((e.localX / e.width) * n)))
          const r = Math.max(0, Math.min(n - 1, Math.floor((e.localY / e.height) * n)))
          // A point of the keys' walk takes its tap itself, and a card over the board its own.
          if (nearAt.has(r * n + c) || frameos.recall('confirm')) return false
          tapPoint(app, r * n + c, twoTaps)
        }}>
        <Board n={n} px={board} t={t} hc={hc} cursor={cursor} />
        <Near n={n} px={board} app={app} twoTaps={twoTaps} />
      </div>
      {overlay}
    </div>
  )

  const undoButton = <UndoButton cls={`flex-1 h-[${buttonH}px] rounded-xl flex items-center justify-center text-[${font}px] font-bold`} t={t} app={app} />
  const newButton = (
    <div className={`flex-1 h-[${buttonH}px] rounded-xl flex items-center justify-center text-[${font}px] font-bold ${t.primary}`}
      onClick={() => askNewGame(app)}>
      New game
    </div>
  )
  const player = (c, stacked) => <Player c={c} stacked={stacked} font={font} t={t} label={name(c)} />

  if (round) {
    const { x0, y0, chord } = roundRoom(W, H)
    const top = (H - outer) >> 1
    const sFont = Math.max(14, Math.min(font, Math.round(y0 * 0.24)))
    const bh = Math.max(36, Math.round(y0 * 0.52))
    const bTop = top + outer + Math.max(6, Math.round(y0 * 0.1))
    const bw = Math.floor((chord(bTop + bh - H / 2) - 10) / 2)
    // In the arc under the board New game may not fit its button: a size
    // smaller does, else New.
    const fitsNew = Math.floor((bw - 8) / 4.96)
    const bFont = Math.max(14, Math.min(font, Math.round(bh * 0.4), fitsNew >= 14 ? fitsNew : font))
    const newLabel = fitsNew >= 14 ? 'New game' : 'New'
    const pFont = Math.max(14, Math.min(font, Math.round(x0 * 0.3)))
    // The names small under the stones, as the arcs beside the board hold them
    // (none under 10 px).
    const small = Math.min(nameSize(pFont), Math.floor((((W - outer) >> 1) - 26) / (0.6 * Math.max(name(1).length, name(2).length))))
    const beside = (left: boolean, c) => (
      <div className={`absolute ${left ? 'left-0 pl-[10px]' : 'right-0 pr-[10px]'} top-0 w-[${(W - outer) >> 1}px] h-[${H}px] flex items-center justify-center`}>
        <Player c={c} stacked={true} bare={small < 10} font={pFont} small={small} t={t} label={name(c)} />
      </div>
    )
    return (
      <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
        <div className={`absolute left-0 top-0 w-[${W}px] h-[${top - Math.max(6, Math.round(y0 * 0.1))}px] flex items-end justify-center`}>
          <Status cls={`max-w-[${chord(H / 2 - y0 + sFont * 2)}px] rounded-xl px-3 py-1 text-[${sFont}px] font-bold truncate ${t.status}`} />
        </div>
        {beside(true, 1)}
        {beside(false, 2)}
        <div className={`absolute left-[${(W - outer) >> 1}px] top-[${top}px]`}>{boardBox}</div>
        <div className={`absolute left-0 top-[${bTop}px] w-[${W}px] flex justify-center gap-[10px]`}>
          <UndoButton cls={`w-[${bw}px] h-[${bh}px] rounded-xl flex items-center justify-center text-[${bFont}px] font-bold`} t={t} app={app} />
          <div className={`w-[${bw}px] h-[${bh}px] rounded-xl flex items-center justify-center text-[${bFont}px] font-bold ${t.primary}`}
            onClick={() => askNewGame(app)}>
            {newLabel}
          </div>
        </div>
      </div>
    )
  }

  if (wide) {
    return (
      <div className={`flex w-full h-full p-[${m}px] gap-[${m}px] items-center ${t.page}`}>
        {boardBox}
        <div className="flex-1 min-w-0 h-full flex flex-col justify-between gap-3">
          <div className="flex flex-col">
            <span className={`text-[${titleAt(font)}px] font-black leading-none ${t.title}`}>Gomoku</span>
            {level ? null : <span className={`text-[${Math.round(font * 0.75)}px] ${t.muted}`}>{subtitle}</span>}
          </div>
          <Status cls={`rounded-xl px-[${Math.round(statusPad(font) * 1.3)}px] py-[${statusPad(font)}px] text-[${font}px] font-bold leading-tight line-clamp-2 ${t.status}`} />
          {level === 2 ? (
            <div className="flex gap-2">
              {player(1, true)}
              {player(2, true)}
            </div>
          ) : (
            <div className="flex flex-col gap-2">
              {player(1, false)}
              {player(2, false)}
              {level ? null : <Played cls={`text-[${Math.round(font * 0.75)}px] ${t.muted}`} />}
            </div>
          )}
          {stacked ? (
            <div className="flex flex-col gap-2">
              <div className="flex">{undoButton}</div>
              <div className="flex">{newButton}</div>
            </div>
          ) : (
            <div className="flex gap-3">
              {undoButton}
              {newButton}
            </div>
          )}
        </div>
      </div>
    )
  }
  // The players beside the status, each name small under its stone, as tall as the row.
  const chipFont = Math.min(font, Math.floor((headerH - 16) / 1.8))
  return (
    <div className={`flex flex-col w-full h-full p-[${m}px] gap-[${m}px] items-center justify-between ${t.page}`}>
      {titled ? (
        <div className={`flex flex-col w-full h-[${titleH}px] justify-end`}>
          <span className={`text-[${Math.round(titleH * 0.62)}px] font-black leading-none ${t.title}`}>Gomoku</span>
          <span className={`text-[${Math.round(font * 0.7)}px] truncate ${t.muted}`}>{subtitle}</span>
        </div>
      ) : null}
      <div className={`flex w-full h-[${headerH}px] items-center gap-2`}>
        <Status cls={`flex-1 min-w-0 rounded-xl px-3 h-full flex items-center text-[${font}px] font-bold truncate ${t.status}`} />
        <Player c={1} stacked={true} font={chipFont} t={t} label={name(1)} />
        <Player c={2} stacked={true} font={chipFont} t={t} label={name(2)} />
      </div>
      {boardBox}
      <div className={`flex w-full h-[${footH}px] gap-3`}>
        {undoButton}
        {newButton}
      </div>
    </div>
  )
}

