// The rules of gomoku (five in a row) and a computer player, with no drawing.
// A game is its board size and the list of moves (cell indexes, row by row);
// the board is worked out from them: 0 empty, 1 black, 2 white. Black plays
// first. Plain values only, so a game fits in the scene's state as JSON.

export type Game = {
  size: number
  moves: number[]
  winner: number // 0 playing, 1 black, 2 white, 3 a draw (the board is full)
  line: number[] // the winning stones, from one end to the other
  seed: number
}

export const DRAW = 3

// The four directions a line can run in: across, down, and the two diagonals.
const DIRS = [
  [0, 1],
  [1, 0],
  [1, 1],
  [1, -1],
]

export function newGame(size: number, seed: number): Game {
  const n = size === 13 || size === 19 ? size : 15
  return { size: n, moves: [], winner: 0, line: [], seed: seed | 0 }
}

export function boardOf(game: Game): number[] {
  const cells = new Array(game.size * game.size).fill(0)
  for (let i = 0; i < game.moves.length; i++) cells[game.moves[i]] = i % 2 === 0 ? 1 : 2
  return cells
}

/** Whose turn it is: 1 black, 2 white. */
export function toMove(game: Game): number {
  return game.moves.length % 2 === 0 ? 1 : 2
}

/**
 * The run of `p`'s stones through `idx` along a direction, as the cells from
 * one end to the other.
 */
function runThrough(cells: number[], size: number, idx: number, p: number, dr: number, dc: number): number[] {
  const r0 = Math.floor(idx / size)
  const c0 = idx % size
  const run = [idx]
  for (const sign of [-1, 1]) {
    let r = r0 + dr * sign
    let c = c0 + dc * sign
    while (r >= 0 && r < size && c >= 0 && c < size && cells[r * size + c] === p) {
      if (sign < 0) run.unshift(r * size + c)
      else run.push(r * size + c)
      r += dr * sign
      c += dc * sign
    }
  }
  return run
}

/** The winning line the stone on `idx` makes, or null. `exact`: six or more do not count. */
export function winningLine(cells: number[], size: number, idx: number, exact: boolean): number[] | null {
  const p = cells[idx]
  if (!p) return null
  for (const [dr, dc] of DIRS) {
    const run = runThrough(cells, size, idx, p, dr, dc)
    if (run.length === 5 || (run.length > 5 && !exact)) return run
  }
  return null
}

/** Places a stone for the side to move; false when the cell is taken or the game is over. */
export function place(game: Game, idx: number, exact: boolean): boolean {
  if (game.winner || idx < 0 || idx >= game.size * game.size) return false
  const cells = boardOf(game)
  if (cells[idx]) return false
  cells[idx] = toMove(game)
  game.moves.push(idx)
  const line = winningLine(cells, game.size, idx, exact)
  if (line) {
    game.winner = cells[idx]
    game.line = line
  } else if (game.moves.length === game.size * game.size) game.winner = DRAW
  return true
}

/** Takes the last stone back. */
export function takeBack(game: Game): boolean {
  if (!game.moves.length) return false
  game.moves.pop()
  game.winner = 0
  game.line = []
  return true
}

/** mulberry32 with its state in the game, so a game's choices are reproducible. */
export function random(game: { seed: number }): number {
  let t = (game.seed = (game.seed + 0x6d2b79f5) | 0)
  t = Math.imul(t ^ (t >>> 15), t | 1)
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296
}

// --- the computer player ---------------------------------------------------

// The nine cells of a line centred on a cell, reused for every look.
const LINE = [0, 0, 0, 0, 0, 0, 0, 0, 0]

/**
 * What a stone of `p` on `idx` would make along one direction. The cells four
 * either side are read, and each of the five windows of five cells holding
 * `idx` that has none of the other side's stones (nor the edge) counts its
 * own stones: the most in a window, and how many windows reach it, tell a
 * five, an open four (two windows of four: _XXXX_), a four, open and closed
 * threes and twos, broken shapes (X_XX) included.
 */
function shapeScore(cells: number[], size: number, idx: number, p: number, dr: number, dc: number): number {
  const r0 = Math.floor(idx / size)
  const c0 = idx % size
  for (let k = -4; k <= 4; k++) {
    const r = r0 + dr * k
    const c = c0 + dc * k
    if (k === 0) LINE[4] = 1
    else if (r < 0 || r >= size || c < 0 || c >= size) LINE[k + 4] = -1
    else {
      const v = cells[r * size + c]
      LINE[k + 4] = v === 0 ? 0 : v === p ? 1 : -1
    }
  }
  let best = 0
  let windows = 0
  for (let w = 0; w <= 4; w++) {
    let n = 0
    let blocked = false
    for (let j = w; j < w + 5; j++) {
      const v = LINE[j]
      if (v < 0) {
        blocked = true
        break
      }
      n += v
    }
    if (blocked) continue
    if (n > best) {
      best = n
      windows = 1
    } else if (n === best) windows++
  }
  if (best >= 5) return 1000000
  if (best === 4) return windows >= 2 ? 100000 : 12000
  if (best === 3) return windows >= 3 ? 6000 : windows === 2 ? 3500 : 400
  if (best === 2) return windows >= 3 ? 300 : windows === 2 ? 150 : 40
  return windows * 4
}

/**
 * What a stone of `p` on `idx` would make, summed over the four directions,
 * with a bonus for two threats at once (two open threes, a four and an open
 * three): the other side can block only one of them.
 */
export function cellScore(cells: number[], size: number, idx: number, p: number): number {
  let total = 0
  let threats = 0
  for (const [dr, dc] of DIRS) {
    const score = shapeScore(cells, size, idx, p, dr, dc)
    total += score
    if (score >= 3500) threats++
  }
  if (threats >= 2 && total < 100000) total += 50000
  return total
}

/** The empty cells within two of a stone: the only ones worth looking at. */
export function candidates(cells: number[], size: number): number[] {
  const near = new Array(cells.length).fill(0)
  for (let i = 0; i < cells.length; i++) {
    if (!cells[i]) continue
    const r = Math.floor(i / size)
    const c = i % size
    for (let dr = -2; dr <= 2; dr++) {
      const rr = r + dr
      if (rr < 0 || rr >= size) continue
      for (let dc = -2; dc <= 2; dc++) {
        const cc = c + dc
        if (cc >= 0 && cc < size) near[rr * size + cc] = 1
      }
    }
  }
  const out: number[] = []
  for (let i = 0; i < cells.length; i++) if (near[i] && !cells[i]) out.push(i)
  return out
}

/**
 * A win by fours (VCF, "victory by continuous fours"): a stone of `me` that
 * makes four leaves the other side one cell to block; after the block,
 * another four, and so on, until a five or an open four. `depth` fours at
 * most, and at most 200 fours tried in all, so it stays quick on a board
 * full of them. Returns the first stone of such a win, or -1.
 */
export function winByFours(cells: number[], size: number, me: number, depth: number): number {
  const them = 3 - me
  // The other side wins first if it already has a four of its own.
  for (const idx of candidates(cells, size)) if (cellScore(cells, size, idx, them) >= 1000000) return -1
  let tries = 0
  const search = (left: number): number => {
    for (const idx of candidates(cells, size)) {
      const made = cellScore(cells, size, idx, me)
      if (made >= 1000000) return idx
      if (made < 12000 || left <= 0 || tries >= 200) continue
      tries++
      cells[idx] = me
      // Where the four would become five: the one cell the other side must take.
      let block = -1
      let blocks = 0
      for (const other of candidates(cells, size)) {
        if (cellScore(cells, size, other, me) >= 1000000) {
          block = other
          blocks++
        }
      }
      let wins = false
      if (blocks >= 2) wins = true // an open four, or two fours: one block is not enough
      else if (blocks === 1 && cellScore(cells, size, block, them) < 1000000) {
        cells[block] = them
        // The block may make a four of the other side's, which comes first.
        let theirFour = false
        for (const other of candidates(cells, size)) {
          if (cellScore(cells, size, other, them) >= 1000000) {
            theirFour = true
            break
          }
        }
        if (!theirFour) wins = search(left - 1) >= 0
        cells[block] = 0
      }
      cells[idx] = 0
      if (wins) return idx
    }
    return -1
  }
  return search(depth)
}

export const LEVELS = {
  // attack and defence weights, how far below the best a move may be picked
  // (a share of the best), how many of the best are looked at a move deeper
  // and how much the other side's best answer counts against each, and how
  // many fours in a row it looks for a forced win with.
  easy: { attack: 1, defence: 0.45, spread: 0.45, deeper: 0, fours: 0 },
  medium: { attack: 1, defence: 0.9, spread: 0.08, deeper: 0, fours: 2 },
  hard: { attack: 1.3, defence: 0.95, spread: 0, deeper: 12, fours: 6, reply: 1 },
}

/**
 * The computer's move: every cell near a stone is scored by what it makes for
 * the computer (attack) and what it takes from the other side (defence): a
 * five first, then blocking the other's five, an open four, blocking a four,
 * open threes and so on. "hard" also plays its best few candidates out and
 * takes off the best answer the other side would have.
 */
export function chooseMove(game: Game, level: string): number {
  const size = game.size
  const cells = boardOf(game)
  const me = toMove(game)
  const them = 3 - me
  const center = Math.floor(size / 2) * size + Math.floor(size / 2)
  if (!game.moves.length) return center
  const cfg = LEVELS[level] || LEVELS.medium
  const list = candidates(cells, size)
  const scored: { idx: number; score: number; mine: number; theirs: number }[] = []
  for (const idx of list) {
    const mine = cellScore(cells, size, idx, me)
    const theirs = cellScore(cells, size, idx, them)
    // A little pull to the middle breaks ties towards room to grow.
    const r = Math.floor(idx / size)
    const c = idx % size
    const middle = size - Math.abs(r - (size - 1) / 2) - Math.abs(c - (size - 1) / 2)
    scored.push({ idx, score: mine * cfg.attack + theirs * cfg.defence + middle, mine, theirs })
  }
  scored.sort((a, b) => b.score - a.score)
  // A five wins, and blocking the other side's five comes before anything else.
  if (scored[0].mine >= 1000000) return scored[0].idx
  const block = scored.find((s) => s.theirs >= 1000000)
  if (block && level !== 'easy') return block.idx
  if (cfg.fours) {
    // A forced win by fours, and else whether the other side has one to stop.
    const win = winByFours(cells, size, me, cfg.fours)
    if (win >= 0) return win
  }
  if (cfg.deeper) {
    let bestIdx = scored[0].idx
    let bestValue = -Infinity
    for (const s of scored.slice(0, cfg.deeper)) {
      cells[s.idx] = me
      // The most the other side could make with its answer. (Not what its
      // answer would block: a move that makes a threat would look bad for
      // the block it calls for.)
      let reply = 0
      for (const idx of candidates(cells, size)) {
        const v = cellScore(cells, size, idx, them)
        if (v > reply) reply = v
      }
      cells[s.idx] = 0
      const value = s.score - reply * cfg.reply
      if (value > bestValue) {
        bestValue = value
        bestIdx = s.idx
      }
    }
    return bestIdx
  }
  const floor = scored[0].score * (1 - cfg.spread)
  const near = scored.filter((s) => s.score >= floor).slice(0, 6)
  return near[Math.floor(random(game) * near.length)].idx
}

/** A game read back from state, or null when it is not one. */
export function readGame(value: any): Game | null {
  if (!value || typeof value !== 'object' || !Array.isArray(value.moves)) return null
  const size = value.size === 13 || value.size === 19 ? value.size : value.size === 15 ? 15 : 0
  if (!size) return null
  return {
    size,
    moves: value.moves.map((v: any) => Number(v) | 0),
    winner: Number(value.winner) || 0,
    line: Array.isArray(value.line) ? value.line.map((v: any) => Number(v) | 0) : [],
    seed: Number(value.seed) | 0,
  }
}
